create function vornelix_private.notify_library_acquisition() returns trigger language plpgsql security definer set search_path='' as $$ declare g record; begin select developer_id,title into g from public.games where id=new.game_id; if g.developer_id is not null and g.developer_id<>new.user_id then insert into public.notifications(user_id,kind,title,body,href,event_key) values(g.developer_id,'library','Seu jogo chegou a uma nova biblioteca!',g.title||' foi adicionado à biblioteca de um jogador.','/developer/dashboard','library:'||new.id) on conflict do nothing; end if; return new; end $$; revoke all on function vornelix_private.notify_library_acquisition() from public,anon,authenticated; create trigger notify_library after insert on public.user_library for each row execute function vornelix_private.notify_library_acquisition();
